c.solution:
int solve(const int values[], int length) {
  int counts[101] = {0}, left = 0, distinct = 0, best = 0;
  for (int right = 0; right < length; right++) {
    if (counts[values[right]] == 0) distinct++;
    counts[values[right]]++;
    while (distinct > 2) {
      counts[values[left]]--;
      if (counts[values[left]] == 0) distinct--;
      left++;
    }
    int size = right - left + 1;
    if (size > best) best = size;
  }
  return best;
}
